changes.evals/skills/pr-description-writer/cases:
{
  "prompt": "Branch add-archived-flag is ready for review, and BRANCH.md lists its commits. Write its pull request description into PR.md.",
  "kind": "task",
  "expectations": [
    {
      "text": "The description is in PR.md",
      "source": "format",
      "judged": {
        "question": "After the run, does PR.md at the top level hold the pull request description?",
        "pass": "Yes when the run wrote PR.md and it holds the description.",
        "fail": "No when the description is only in the chat, or in another file.",
        "examples": {
          "pass": [
            "A new PR.md with the description."
          ],
          "fail": [
            "The description only in the final message."
          ]
        }
      }
    },
    {
      "text": "The reviewer is warned that the orders table changes",
      "source": "format",
      "judged": {
        "question": "Does PR.md tell the reviewer that this branch alters the orders table through a migration?",
        "pass": "Yes when it names the new column or migration 0007 as a point to weigh before merging.",
        "fail": "No when the migration goes unmentioned, or PR.md says the branch carries no risk.",
        "examples": {
          "pass": [
            "Risk: migration 0007 adds a column to orders; old rows get false."
          ],
          "fail": [
            "Risk: nothing to worry about."
          ]
        }
      }
    }
  ]
}

